import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        long MOD = 1000000007L;
        boolean[] visited_flags = new boolean[1000010];
        long answer = 1;

        if (k != 0) {
            int inv_k = 0;
            if (k == 1) {
                answer = p;
            }
            // Find modular inverse of k modulo p
            for (int i = 1; i < p; i++) {
                if ((long) i * k % p == 1) {
                    inv_k = i;
                    break;
                }
            }
            for (int i = 1; i < p; i++) {
                if (!visited_flags[i]) {
                    visited_flags[i] = true;
                    int count = 1;
                    int j = (int) ((long) k * i % p);
                    int m = inv_k;
                    while (!visited_flags[j]) {
                        visited_flags[j] = true;
                        count++;
                        m = (int) ((long) m * inv_k % p);
                        j = (int) ((long) k * j % p);
                    }
                    if (m == 1) {
                        answer = (answer * p) % MOD;
                    }
                }
            }
        } else {
            for (int i = 1; i < p; i++) {
                answer = (answer * p) % MOD;
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
